{
  "subtype": "faceted_decomposition",
  "concept": "audience_praise_and_complaints",
  "per_column": [
    {
      "name": "praise_count",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "The volume of praise is a constitutive aspect of the praise-and-complaints concept, capturing the 'praise' side quantitatively as a part of the whole."
    },
    {
      "name": "complaint_count",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "The volume of complaints is a constitutive aspect of the concept, capturing the 'complaints' side quantitatively as a part of the whole."
    },
    {
      "name": "praised_aspects",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Identifies WHICH aspects (acting, plot, etc.) are praised -- a constitutive content-facet of the praise dimension, an aspect-of the concept."
    },
    {
      "name": "complained_aspects",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Identifies which aspects are complained about -- a constitutive content-facet of the complaint dimension, an aspect-of the concept."
    },
    {
      "name": "review_sentiment_type",
      "is_constitutive_facet": false,
      "role": "restatement",
      "rationale": "This categorizes the review as predominantly_praise / predominantly_complaint / mixed / neutral, which is a summary label re-derived from the balance of praise vs complaint already captured by the count columns. It restates the whole concept rather than decomposing it into a distinct part."
    }
  ],
  "facet_columns": ["praise_count", "complaint_count", "praised_aspects", "complained_aspects"],
  "non_facet_columns": ["review_sentiment_type"],
  "mutual_exclusivity": 0.7,
  "exhaustiveness": 0.75,
  "rationale": "The concept 'audience_praise_and_complaints' decomposes naturally into two polarity sides (praise, complaint), each with a volume dimension (counts) and a content/aspect dimension (which topics). The four count/aspect columns are genuine constitutive facets and cover both polarity x (volume, content) cells fairly well, giving reasonable exhaustiveness. Mutual exclusivity is somewhat reduced because review_sentiment_type is a restatement derived from the same praise/complaint balance the counts already encode, overlapping rather than carving a new aspect. Missing constitutive dimensions such as intensity/strength of the sentiment and specific evaluative expressions keep exhaustiveness below full."
}

